<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import AccountingOverview from './AccountingOverview.vue';
import AccountingTrade from './AccountingTrade.vue';
import AccountingTransactions from './AccountingTransactions.vue';
import AdminDialog from '../../AdminDialog.vue';
import './accounting.css';
type Account={version:number;id:number;company_id:number;parent_id:number|null;code:string;name:string;root_type:string;account_type:string;is_group:boolean;is_system:boolean;active:boolean;description:string|null};
type Data={book:any;companies:{id:number;name:string}[];company_id:number|null;role:string;can_manage:boolean;can_delete:boolean;account_types:Record<string,string[]>;accounts:Account[]};
const selectedLedger=ref('');
const sections=[{id:'overview',name:'Overview'},{id:'customers',name:'Customers'},{id:'suppliers',name:'Suppliers'},{id:'sales',name:'Sales invoices'},{id:'purchases',name:'Purchase invoices'},{id:'chart',name:'Chart of accounts'},{id:'journals',name:'Journal entries'},{id:'ledger',name:'General Ledger'},{id:'trial',name:'Trial Balance'},{id:'profit',name:'Profit and Loss'},{id:'balance',name:'Balance Sheet'},{id:'receivables',name:'Accounts receivable'},{id:'payables',name:'Accounts payable'},{id:'books',name:'Company books'},{id:'audit',name:'Audit history'}];
const navGroups=[{label:'Workspace',ids:['overview']},{label:'Sales',ids:['customers','sales','receivables']},{label:'Purchases',ids:['suppliers','purchases','payables']},{label:'Accounting',ids:['chart','journals','ledger']},{label:'Financial reports',ids:['trial','profit','balance']},{label:'Administration',ids:['books','audit']}];
const section=ref(sections.some(s=>s.id===location.hash.slice(1))?location.hash.slice(1):'overview');
function navigate(id:string){section.value=id;history.replaceState(null,'','#'+id);mobileNav.value=false;}
const props=defineProps<{csrf?:string}>();
const data=ref<Data|null>(null),company=ref(new URLSearchParams(location.search).get('company_id')||''),search=ref(''),root=ref(''),kind=ref(''),state=ref(''),selectedId=ref<number|null>(null),expanded=ref(new Set<number>()),loading=ref(true),busy=ref(false),error=ref(''),formError=ref(''),notice=ref(''),failed=ref(false),modal=ref(''),mobileNav=ref(false);
const form=ref<any>({});let version=0,timer:ReturnType<typeof setTimeout>|undefined;
const accounts=computed(()=>data.value?.accounts||[]),selected=computed(()=>accounts.value.find(a=>a.id===selectedId.value));
const companyName=computed(()=>data.value?.companies.find(c=>String(c.id)===company.value)?.name||'Select a company');
const matching=(a:Account)=>(!root.value||a.root_type===root.value)&&(!kind.value||(kind.value==='group')===a.is_group)&&(!state.value||(state.value==='active')===a.active)&&(!search.value||[a.code,a.name,a.description||''].join(' ').toLowerCase().includes(search.value.toLowerCase()));
const filtering=computed(()=>!!(search.value||root.value||kind.value||state.value));
const matches=computed(()=>accounts.value.filter(matching));
const children=computed(()=>{const map=new Map<number|null,Account[]>();for(const a of accounts.value)map.set(a.parent_id,[...(map.get(a.parent_id)||[]),a]);return map;});
const rows=computed(()=>{const allowed=new Set<number>();for(const a of matches.value){let cursor:Account|undefined=a;while(cursor&&!allowed.has(cursor.id)){allowed.add(cursor.id);cursor=accounts.value.find(p=>p.id===cursor!.parent_id);}}
 const result:{account:Account;depth:number;hasChildren:boolean}[]=[];const visited=new Set<number>();function walk(parent:number|null,depth:number){for(const a of children.value.get(parent)||[]){if(visited.has(a.id)||!allowed.has(a.id))continue;visited.add(a.id);const kids=children.value.get(a.id)||[];result.push({account:a,depth,hasChildren:kids.length>0});if(filtering.value||expanded.value.has(a.id))walk(a.id,depth+1);}}walk(null,0);return result;});
const path=computed(()=>{const result:Account[]=[];let current=selected.value;const seen=new Set<number>();while(current&&!seen.has(current.id)){seen.add(current.id);result.unshift(current);current=accounts.value.find(a=>a.id===current!.parent_id);}return result;});
const parents=computed(()=>accounts.value.filter(a=>{if(!a.is_group||a.root_type!==form.value.root_type||form.value.active&&!a.active)return false;let cursor:Account|undefined=a;const seen=new Set<number>();while(cursor&&!seen.has(cursor.id)){if(cursor.id===form.value.id)return false;seen.add(cursor.id);cursor=accounts.value.find(p=>p.id===cursor!.parent_id);}return true;}));
function notify(message:string,isError=false){notice.value=message;failed.value=isError;clearTimeout(timer);timer=setTimeout(()=>notice.value='',4500);}
async function api(path:string,body?:any,method='POST'){const response=await fetch('/accounting/api/'+path,{method:body?method:'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const result=await response.json();if(!response.ok)throw Object.assign(Error(Object.values(result.errors||{}).flat().join(' ')||result.message||'Unable to complete this action.'),{status:response.status});return result;}
async function load(reset=false){const current=++version;loading.value=true;error.value='';try{const result=await api('data'+(company.value?'?company_id='+company.value:''));if(current!==version)return;data.value=result;company.value=String(result.company_id||'');const url=new URL(location.href);if(company.value)url.searchParams.set('company_id',company.value);else url.searchParams.delete('company_id');history.replaceState(null,'',url);if(reset){selectedId.value=null;search.value='';root.value='';kind.value='';state.value='';}if(reset||!expanded.value.size)expanded.value=new Set(result.accounts.filter((a:Account)=>a.is_group).map((a:Account)=>a.id));if(selectedId.value&&!result.accounts.some((a:Account)=>a.id===selectedId.value))selectedId.value=null;}catch(e){if(current===version)error.value=(e as Error).message;}finally{if(current===version)loading.value=false;}}
function toggle(id:number){const next=new Set(expanded.value);next.has(id)?next.delete(id):next.add(id);expanded.value=next;}
function open(kind:string,account?:Account){formError.value='';modal.value=kind;if(kind==='edit'&&account)form.value={...account};else if(kind==='delete')form.value={...account};else if(kind==='create'){const parent=account?.is_group?account:accounts.value.find(a=>a.is_system&&a.root_type===(selected.value?.root_type||'Asset'));form.value={company_id:Number(company.value),parent_id:parent?.id||'',code:'',name:'',root_type:parent?.root_type||'Asset',account_type:'General',is_group:false,active:true,description:''};}}
function resetParent(){form.value.parent_id='';form.value.account_type='General';}
async function save(){if(busy.value)return;busy.value=true;formError.value='';try{let response;if(modal.value==='initialize')response=await api('initialize',{company_id:Number(company.value)});else if(modal.value==='delete')response=await api('accounts/'+form.value.id,{company_id:Number(company.value),version:form.value.version},'DELETE');else response=await api('accounts',form.value);if(response.account)selectedId.value=response.account.id;modal.value='';notify(response.message);await load();}catch(e){formError.value=(e as Error).message;notify(formError.value,true);if((e as any).status===409)await load();}finally{busy.value=false;}}
function filterReset(){search.value='';root.value='';kind.value='';state.value='';}
onMounted(()=>void load(true));onBeforeUnmount(()=>{version++;clearTimeout(timer);});
</script>
<template><div class="ac-workspace">
<div v-if="notice" class="judibas-toast" :class="{error:failed}" role="status">{{notice}}</div>
<header class="ac-heading"><div><p class="eyebrow">JUDIBAS / FINANCE</p><h1>Accounting</h1><p class="muted">A clear foundation for your company's finances.</p></div><label v-if="data?.companies.length" class="ac-company">Company<select v-model="company" :disabled="busy||loading" @change="load(true)"><option v-for="c in data.companies" :key="c.id" :value="String(c.id)">{{c.name}}</option></select></label></header>
<div class="ac-layout"><aside class="ac-sidebar"><button class="ac-mobile-nav" type="button" :aria-expanded="mobileNav" @click="mobileNav=!mobileNav">Accounting navigation <span aria-hidden="true">{{mobileNav?'-':'+'}}</span></button><nav aria-label="Accounting navigation" :class="{open:mobileNav}"><template v-for="group in navGroups" :key="group.label"><p class="eyebrow ac-nav-group">{{group.label}}</p><button v-for="item in sections.filter(s=>group.ids.includes(s.id)&&(s.id!=='audit'||data?.can_delete))" :key="item.id" type="button" :class="{active:section===item.id}" :aria-current="section===item.id?'page':undefined" @click="navigate(item.id)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path :d="['sales','purchases','journals'].includes(item.id)?'M6 3h12v18H6z M9 8h6 M9 12h6 M9 16h4':['customers','suppliers'].includes(item.id)?'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 8h5 M19.5 5.5v5':'M4 20h16 M6 16V9 M12 16V4 M18 16v-6'"/></svg>{{item.name}}</button></template><a href="/products">All products <span aria-hidden="true">&#8599;</span></a></nav><div class="ac-scope"><strong>{{companyName}}</strong><small>{{({manager:'Accounting Manager',accountant:'Accountant',viewer:'Read-only access'} as any)[data?.role||'viewer']}}</small></div></aside>
<main class="ac-main" :aria-busy="loading"><AccountingOverview v-if="section==='overview'&&data?.company_id" :company="data.company_id" :book="data.book" @navigate="navigate"/><AccountingTrade v-else-if="['customers','suppliers','sales','purchases'].includes(section)&&data?.company_id" :key="'trade-'+data.company_id" :section="section" :company="data.company_id" :book="data.book" :accounts="accounts" :can-manage="data.can_manage" :can-admin="data.can_delete" :csrf="csrf" @notice="notify($event)" @setup="navigate('books')"/><AccountingTransactions v-else-if="section!=='chart'&&data?.company_id" :key="data.company_id" :section="section" :company="data.company_id" :company-name="companyName" :book="data.book" :accounts="accounts" :can-manage="data.can_manage" :can-admin="data.can_delete" :csrf="csrf" @ledger="selectedLedger=String($event);navigate('ledger')" :initial-account="selectedLedger" @changed="load()" @notice="notify($event)"/><template v-else><div class="ac-section-heading"><div><h2>Chart of accounts</h2><p class="muted">Organise accounts into Assets, Liabilities, Equity, Income and Expenses.</p></div><button v-if="data?.can_manage&&accounts.length" class="button primary" :disabled="busy||loading" @click="open('create',selected)">+ Create account</button></div>
<p v-if="error" class="notice admin-error" role="alert">{{error}} <button class="button" @click="load()">Try again</button></p><p v-if="loading&&!data" role="status">Loading your chart...</p>
<template v-if="data&&!error"><div v-if="!data.companies.length" class="ac-empty"><h3>No company assigned</h3><p>Ask your administrator to assign a company to your Accounting access.</p></div>
<div v-else-if="!accounts.length&&!loading" class="ac-empty"><span class="ac-empty-icon" aria-hidden="true">&#8801;</span><h3>Start your company's chart</h3><p>Create a starter structure with five protected root groups and common service-business accounts. You can adapt the account codes and groups to your needs.</p><button v-if="data.can_manage" class="button primary" @click="open('initialize')">Set up chart of accounts</button><p v-else class="muted">An accountant or administrator can set up this company's chart.</p></div>
<template v-else-if="accounts.length"><div class="ac-stats"><article><small>Total accounts</small><strong>{{accounts.length}}</strong></article><article><small>Groups</small><strong>{{accounts.filter(a=>a.is_group).length}}</strong></article><article><small>Ledger accounts</small><strong>{{accounts.filter(a=>!a.is_group).length}}</strong></article><article><small>Inactive</small><strong>{{accounts.filter(a=>!a.active).length}}</strong></article></div>
<div class="ac-filters"><label class="ac-search">Find an account<input type="search" v-model="search" placeholder="Search by code, name or description"></label><label>Root type<select v-model="root"><option value="">All root types</option><option v-for="(_,name) in data.account_types" :key="name" :value="name">{{name}}</option></select></label><label>Account kind<select v-model="kind"><option value="">All accounts</option><option value="group">Groups</option><option value="ledger">Ledger accounts</option></select></label><label>Status<select v-model="state"><option value="">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option></select></label><button v-if="filtering" type="button" class="button" @click="filterReset">Clear filters</button></div>
<div class="ac-chart-layout" :class="{'has-selection':!!selected}"><section class="ac-tree-panel"><header><div><h3>Account hierarchy</h3><small class="muted">{{filtering?matches.length+' matching accounts':'Select an account to view its details'}}</small></div><div class="ac-tree-controls"><button type="button" @click="expanded=new Set(accounts.filter(a=>a.is_group).map(a=>a.id))">Expand all</button><button type="button" @click="expanded=new Set()">Collapse all</button></div></header>
<div class="ac-chart-columns"><span>Account code / name</span><span>Account type</span><span>Status</span></div><div class="ac-tree" role="tree" aria-label="Chart of accounts"><div v-for="row in rows" :key="row.account.id" role="treeitem" :aria-level="row.depth+1" :aria-expanded="row.account.is_group?(filtering||expanded.has(row.account.id)):undefined" :aria-selected="selectedId===row.account.id" class="ac-tree-row" :class="{selected:selectedId===row.account.id,inactive:!row.account.active,context:filtering&&!matching(row.account),group:row.account.is_group,root:row.account.is_system}" :style="{'--depth':Math.min(row.depth,5)}"><button v-if="row.hasChildren" type="button" class="ac-toggle" :aria-label="(expanded.has(row.account.id)?'Collapse ':'Expand ')+row.account.name" @click="toggle(row.account.id)"><svg viewBox="0 0 20 20" :class="{rotated:filtering||expanded.has(row.account.id)}" aria-hidden="true"><path d="m7 4 6 6-6 6"/></svg></button><span v-else class="ac-toggle-spacer"></span><button type="button" class="ac-account" @click="selectedId=row.account.id"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path :d="row.account.is_group?'M3 6h7l2 2h9v12H3z':'M6 3h12v18H6z M9 8h6 M9 12h6 M9 16h4'"/></svg><code>{{row.account.code}}</code><span>{{row.account.name}}<small>{{row.account.is_group?'Group':'Ledger account'}}{{!row.account.active?' / Inactive':''}}</small></span></button><span class="ac-chart-type">{{row.account.is_group?'Group':row.account.account_type}}</span><span class="ac-chart-state" :class="{inactive:!row.account.active}">{{row.account.active?'Active':'Inactive'}}</span></div></div><p v-if="!rows.length" class="ac-empty-small">No matching accounts. Try another search or clear the filters.</p></section>
<aside v-if="selected" class="ac-detail"><template v-if="selected"><div class="ac-detail-heading"><button type="button" class="ac-detail-close" aria-label="Close account details" @click="selectedId=null">&times;</button><span class="ac-badge" :class="selected.active?'active':'inactive'">{{selected.active?'Active':'Inactive'}}</span><span class="muted">{{selected.is_group?'Group account':'Ledger account'}}</span></div><code class="ac-detail-code">{{selected.code}}</code><h3>{{selected.name}}</h3><p class="ac-path">{{path.map(a=>a.name).join(' / ')}}</p><dl><div><dt>Root type</dt><dd>{{selected.root_type}}</dd></div><div><dt>Account type</dt><dd>{{selected.account_type}}</dd></div><div><dt>Parent group</dt><dd>{{accounts.find(a=>a.id===selected?.parent_id)?.name||'Root group'}}</dd></div></dl><p class="ac-description">{{selected.description||'No description added.'}}</p><p v-if="selected.is_system" class="ac-help">This root group keeps the account tree organised. Manage the accounts below it.</p><div class="ac-detail-actions"><button v-if="data.can_manage&&selected.is_group&&selected.active" class="button primary" :disabled="busy||loading" @click="open('create',selected)">Add child account</button><button v-if="data.can_manage&&!selected.is_system" class="button" :disabled="busy||loading" @click="open('edit',selected)">Edit account</button><button v-if="data.can_delete&&!selected.is_system" class="button ac-danger" :disabled="busy||loading" @click="open('delete',selected)">Delete</button></div></template><template v-else><span class="eyebrow">ACCOUNT DETAILS</span><h3>A place for every account</h3><p class="muted">Select a group or ledger account to see its position in the chart and available actions.</p></template></aside></div>
<p class="ac-stage-note">Use Journal entries to record transactions. Only posted entries appear in the General Ledger and financial reports.</p></template></template></template></main></div>
<AdminDialog v-if="modal" :title="modal==='initialize'?'Set up chart of accounts':modal==='delete'?'Delete account':modal==='edit'?'Edit account':'Create account'" :busy="busy" dialog-class="ac-dialog" @close="!busy&&(modal='')"><form @submit.prevent="save"><p v-if="formError" class="notice admin-error" role="alert">{{formError}}</p>
<template v-if="modal==='initialize'"><p>Create a starter chart for <strong>{{companyName}}</strong>?</p><p class="muted">Includes Assets, Liabilities, Equity, Income and Expenses, with common accounts for cash, bank, receivables, payables and service-business costs. No balances or transactions are created.</p><p class="ac-help">Review the structure with your accountant. This is a starting point, not a country-specific statutory template.</p></template>
<template v-else-if="modal==='delete'"><p>Delete <strong>{{form.code}} - {{form.name}}</strong>?</p><p class="muted">Groups containing accounts cannot be deleted. You can deactivate an account instead to keep its structure.</p></template>
<template v-else><div class="ac-form-grid"><label>Account code<input v-model="form.code" required maxlength="20" pattern="[A-Za-z0-9][A-Za-z0-9.\-]*" placeholder="e.g. 5120" :disabled="busy"></label><label>Account name<input v-model="form.name" required maxlength="150" placeholder="e.g. Internet and telephone" :disabled="busy"></label><label>Root type<select aria-label="Root type" v-model="form.root_type" :disabled="!!form.id||busy" @change="resetParent"><option v-for="(_,name) in data?.account_types" :key="name">{{name}}</option></select></label><label>Account kind<select aria-label="Account kind" v-model="form.is_group" :disabled="!!form.id||busy" @change="form.account_type='General'"><option :value="false">Ledger account</option><option :value="true">Group</option></select></label><label>Parent group<select aria-label="Parent group" v-model.number="form.parent_id" required :disabled="busy"><option value="">Select a parent group</option><option v-for="parent in parents" :key="parent.id" :value="parent.id">{{parent.code}} - {{parent.name}}</option></select></label><label>Account type<select aria-label="Account type" v-model="form.account_type" :disabled="form.is_group||busy"><option v-for="type in data?.account_types[form.root_type]||[]" :key="type">{{type}}</option></select></label></div><label>Description<textarea v-model="form.description" rows="3" maxlength="2000" :disabled="busy" placeholder="Explain what belongs in this account"></textarea></label><label class="ac-check"><input type="checkbox" v-model="form.active" :disabled="busy">Active account</label></template>
<div class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="modal=''">Cancel</button><button class="button primary" :class="{'ac-delete-button':modal==='delete'}" :disabled="busy" :aria-busy="busy"><span v-if="busy" class="ac-spinner" aria-hidden="true"></span>{{busy?'Saving...':modal==='initialize'?'Create starter chart':modal==='delete'?'Delete account':'Save account'}}</button></div></form></AdminDialog>
</div></template>
